#include <iostream>
using namespace std;

int main() {
    long long a, m;
    cin >> a >> m;

    auto next = [m](long long x) {
        return static_cast<long long>((__int128)x * 2 % m);
    };

    long long start = ((a % m) + m) % m;
    long long slow = next(start);
    long long fast = next(next(start));

    while (slow != fast) {
        slow = next(slow);
        fast = next(next(fast));
    }

    cout << (slow == 0 ? "Yes" : "No");
    return 0;
}

